/**
 * BaseTransportService - gemeinsame Basisklasse für alle ÖPNV-Backend-Services
 * (HAFAS, db-vendo, MOTIS).
 *
 * Alle drei Backends sprechen dieselbe `hafas-client`-kompatible API. Diese Klasse
 * bündelt daher den kompletten gemeinsamen Code (Client-Lebenszyklus + die vier
 * Abfrage-Methoden) an einer Stelle. Die konkreten Services müssen nur noch festlegen,
 * WIE ihr Client erzeugt wird (`createClient()`) und WIE sie heißen (`serviceName`).
 *
 * Zusätzlich kapselt sie die Fehlerbehandlung: Jeder Backend-Aufruf läuft durch
 * `call()`, das einen Timeout setzt und vorübergehende (transiente) Fehler automatisch
 * wiederholt.
 */
import type * as Hafas from 'hafas-client';
import type { PublicTransport } from '../../main';
import type { ITransportService } from '../types/transportService';

/**
 * Maximale Anzahl zusätzlicher Wiederholungsversuche bei transienten Backend-Fehlern
 * (z.B. Server-5xx, Netzwerkfehler, Rate-Limit). Der erste Versuch zählt NICHT mit:
 * Bei dem Wert 2 wird ein Request also insgesamt bis zu 3-mal ausgeführt (1 + 2 Retries).
 */
const TRANSPORT_MAX_RETRIES = 2;

/**
 * Basis-Wartezeit in Millisekunden zwischen zwei Versuchen. Die tatsächliche Pause wächst
 * linear mit der Versuchsnummer (vor dem 1. Retry 1×, vor dem 2. Retry 2× usw.), damit ein
 * kurzzeitig gestörtes Backend nicht sofort erneut mit Anfragen überrollt wird (einfacher
 * "Backoff"). Bei 500 ms wird also 500 ms, dann 1000 ms gewartet.
 */
const TRANSPORT_RETRY_DELAY_MS = 500;

/**
 * Maximale Dauer in Millisekunden, die ein EINZELNER Backend-Aufruf dauern darf, bevor er
 * als fehlgeschlagen gilt. Verhindert, dass ein hängender Request den gesamten (sequentiell
 * ablaufenden) Poll-Durchlauf blockiert. Gilt pro Versuch – nicht über alle Wiederholungen
 * zusammengerechnet.
 */
const TRANSPORT_REQUEST_TIMEOUT_MS = 30_000;

/**
 * Transiente Netzwerk-Fehlercodes der Node-/fetch-Schicht. Solche Fehler entstehen NICHT im
 * Backend selbst, sondern beim Verbindungsaufbau (DNS, TCP, TLS) und werden von `hafas-client`
 * unveraendert durchgereicht – ohne `shouldRetry`/`isCausedByServer`-Markierung. Sie sind fast
 * immer voruebergehend (z.B. "Client network socket disconnected before secure TLS connection
 * was established" => ECONNRESET) und daher gefahrlos wiederholbar.
 */
const TRANSIENT_NETWORK_ERROR_CODES: ReadonlySet<string> = new Set([
    'ECONNRESET', // Verbindung vom Gegenüber/Netzwerk abrupt geschlossen (auch TLS-Handshake-Abbruch)
    'ECONNREFUSED', // Server hat die Verbindung (gerade) abgelehnt
    'ECONNABORTED', // Verbindung lokal abgebrochen
    'ETIMEDOUT', // TCP-/Socket-Timeout beim Verbindungsaufbau
    'ESOCKETTIMEDOUT', // Socket-Inaktivitäts-Timeout
    'EPIPE', // Schreiben auf bereits geschlossene Verbindung
    'ENETUNREACH', // Netzwerk vorübergehend nicht erreichbar
    'EHOSTUNREACH', // Host vorübergehend nicht erreichbar
    'EAI_AGAIN', // temporärer DNS-Auflösungsfehler
    'UND_ERR_CONNECT_TIMEOUT', // undici: Timeout beim Verbindungsaufbau
    'UND_ERR_SOCKET', // undici: Socket vorzeitig geschlossen
]);

export abstract class BaseTransportService implements ITransportService {
    protected client: Hafas.HafasClient | null = null;
    protected readonly adapter: PublicTransport;
    protected readonly clientName: string;

    /**
     * IDs der Produkte, die das aktive Profil kennt (z.B. 'express-train', 's-bahn').
     * Wird vom konkreten Service in {@link createClient} via {@link setProfileProducts}
     * gesetzt. `null` bedeutet "unbekannt" – dann wird NICHT gefiltert (kein Regressionsrisiko
     * für Profile ohne Produktliste).
     */
    protected supportedProductIds: ReadonlySet<string> | null = null;

    /**
     * @param adapter Die Adapter-Instanz (liefert die ioBroker-Timer für Timeout/Backoff,
     *                die beim Shutdown automatisch aufgeräumt werden)
     * @param clientName Name/User-Agent, der an den Backend-Client übergeben wird
     */
    constructor(adapter: PublicTransport, clientName: string) {
        this.adapter = adapter;
        this.clientName = clientName;
    }

    /**
     * Erzeugt den konkreten Backend-Client. Einziger echter Unterschied zwischen den
     * Services – wird von `init()` aufgerufen.
     */
    protected abstract createClient(): Hafas.HafasClient;

    /**
     * Sprechender Name des Service (z.B. "HAFAS") für Fehler- und Timeout-Meldungen.
     */
    protected abstract get serviceName(): string;

    /**
     * Initialisiert den Backend-Client. Muss vor der Nutzung der Abfrage-Methoden
     * aufgerufen werden. Wirft bei einem Fehler – ein Rückgabewert wird nicht benötigt.
     */
    public init(): void {
        try {
            this.client = this.createClient();
        } catch (error) {
            throw new Error(`The ${this.serviceName} client could not be initialized: ${(error as Error).message}`);
        }
    }

    /**
     * Gibt den initialisierten Client zurück oder wirft einen Fehler.
     */
    protected getClient(): Hafas.HafasClient {
        if (!this.client) {
            throw new Error(`${this.serviceName}Service has not been initialized yet. Please call init() first.`);
        }
        return this.client;
    }

    /**
     * Führt einen Backend-Aufruf mit Timeout und automatischer Wiederholung aus.
     *
     * Ablauf: Der Aufruf wird gestartet und mit {@link TRANSPORT_REQUEST_TIMEOUT_MS}
     * zeitlich begrenzt. Schlägt er mit einem transienten Fehler fehl (siehe
     * {@link isRetryable}), wird nach einer wachsenden Pause erneut versucht – bis zu
     * {@link TRANSPORT_MAX_RETRIES}-mal. Nicht-transiente Fehler (z.B. ungültige Anfrage)
     * werden sofort weitergereicht.
     *
     * @param operation Die eigentliche Client-Operation
     * @returns Das Ergebnis des Aufrufs
     */
    private async call<T>(operation: (client: Hafas.HafasClient) => Promise<T>): Promise<T> {
        let lastError: unknown;
        for (let attempt = 0; attempt <= TRANSPORT_MAX_RETRIES; attempt++) {
            try {
                return await this.withTimeout(operation(this.getClient()));
            } catch (error) {
                lastError = error;
                if (!this.isRetryable(error) || attempt === TRANSPORT_MAX_RETRIES) {
                    break;
                }
                // ioBroker-eigenes delay(): wird beim Adapter-Shutdown sauber aufgelöst.
                await this.adapter.delay(TRANSPORT_RETRY_DELAY_MS * (attempt + 1));
            }
        }
        throw lastError;
    }

    /**
     * Entscheidet, ob ein Fehler vorübergehend (transient) und damit wiederholbar ist.
     * `hafas-client` markiert solche Fehler mit `shouldRetry`; Server-5xx zusätzlich mit
     * `isCausedByServer`. Eigene Timeout-Fehler werden ebenfalls als wiederholbar gewertet.
     * Zusätzlich werden reine Netzwerkfehler der fetch-/Node-Schicht (DNS/TCP/TLS) erkannt,
     * die `hafas-client` ohne diese Markierungen durchreicht (siehe
     * {@link TRANSIENT_NETWORK_ERROR_CODES}).
     *
     * @param error Der aufgetretene Fehler
     */
    private isRetryable(error: unknown): boolean {
        const e = error as
            | {
                  shouldRetry?: boolean;
                  isCausedByServer?: boolean;
                  isTimeout?: boolean;
                  code?: unknown;
                  cause?: unknown;
                  hafasCode?: string;
              }
            | undefined;
        // H890 "journeys search unsuccessful" markiert hafas-client zwar als shouldRetry,
        // ist bei eingeschränkten Suchparametern (z. B. transfers=0 ohne Direktverbindung)
        // aber deterministisch: ein sofortiger Retry liefert dasselbe Ergebnis und kostet nur
        // Zeit. Der nächste Poll-Zyklus versucht es ohnehin erneut.
        if (e?.hafasCode === 'H890') {
            return false;
        }
        if (e?.shouldRetry === true || e?.isCausedByServer === true || e?.isTimeout === true) {
            return true;
        }
        // Fehlercode kann direkt am Fehler oder (bei modernem fetch) in `cause` hängen.
        const code = typeof e?.code === 'string' ? e.code : undefined;
        const causeCode =
            e?.cause && typeof (e.cause as { code?: unknown }).code === 'string'
                ? (e.cause as { code: string }).code
                : undefined;
        return (
            (code !== undefined && TRANSIENT_NETWORK_ERROR_CODES.has(code)) ||
            (causeCode !== undefined && TRANSIENT_NETWORK_ERROR_CODES.has(causeCode))
        );
    }

    /**
     * Begrenzt eine Promise zeitlich. Läuft sie länger als {@link TRANSPORT_REQUEST_TIMEOUT_MS},
     * wird mit einem als wiederholbar markierten Timeout-Fehler abgelehnt. Der zugrunde
     * liegende Request kann im Hintergrund weiterlaufen, blockiert aber den Ablauf nicht mehr.
     *
     * @param promise Die zu begrenzende Promise
     */
    private withTimeout<T>(promise: Promise<T>): Promise<T> {
        let timer: ioBroker.Timeout | undefined;
        const timeout = new Promise<never>((_resolve, reject) => {
            // ioBroker-eigener Timer: wird beim Adapter-Shutdown automatisch aufgeräumt.
            timer = this.adapter.setTimeout(() => {
                const err = new Error(
                    `${this.serviceName} request timed out after ${TRANSPORT_REQUEST_TIMEOUT_MS} ms`,
                ) as Error & { isTimeout: boolean };
                err.isTimeout = true;
                reject(err);
            }, TRANSPORT_REQUEST_TIMEOUT_MS);
        });
        // Es gewinnt, was zuerst fertig ist: das eigentliche Ergebnis oder der Timeout.
        // Der originale Fehler des Aufrufs wird unveraendert weitergereicht (wichtig fuer
        // isRetryable). Der Timer wird in jedem Fall aufgeräumt.
        return Promise.race([promise, timeout]).finally(() => this.adapter.clearTimeout(timer));
    }

    /**
     * Merkt sich die vom aktiven Profil unterstützten Produkt-IDs. Wird vom konkreten Service
     * in {@link createClient} mit dem dort verwendeten Profil aufgerufen, damit unbekannte
     * Produkt-Filter vor dem Backend-Aufruf entfernt werden können (siehe {@link sanitizeProducts}).
     *
     * @param profile Das HAFAS-kompatible Profil, mit dem der Client erzeugt wird
     * @param profile.products Die vom Profil unterstützten Produkte, deren `id` als Filter gemerkt wird
     */
    protected setProfileProducts(profile: { products?: ReadonlyArray<{ id?: string }> }): void {
        const ids = (profile?.products ?? [])
            .map(p => p?.id)
            .filter((id): id is string => typeof id === 'string' && id.length > 0);
        this.supportedProductIds = ids.length > 0 ? new Set(ids) : null;
    }

    /**
     * Entfernt aus `options.products` alle Produkt-Keys, die das aktive Profil nicht kennt.
     *
     * Hintergrund: `hafas-client` wirft `unknown product <id>`, sobald ein dem Profil unbekanntes
     * Produkt auf `true` gesetzt ist (siehe `format/products-filter.js`). Da die Admin-UI je nach
     * Profil unpassende Produkte liefern kann (oder eine bestehende Konfiguration nach einem
     * Profilwechsel veraltet ist), würde sonst die komplette Abfrage scheitern. Unbekannte Keys
     * werden daher still verworfen; bekannte Produkte bleiben unangetastet.
     *
     * Es wird ein flacher Klon zurückgegeben – die übergebenen Optionen bleiben unverändert.
     *
     * @param options Die Abfrage-Optionen (können `products` enthalten)
     * @returns Die Optionen mit bereinigter Produktliste (oder unverändert, wenn nichts zu tun ist)
     */
    protected sanitizeProducts<T extends { products?: Hafas.Products }>(options?: T): T | undefined {
        const supported = this.supportedProductIds;
        if (!options?.products || !supported) {
            return options;
        }
        const entries = Object.entries(options.products);
        const dropped = entries.filter(([id]) => !supported.has(id)).map(([id]) => id);
        if (dropped.length === 0) {
            return options;
        }
        const products: Hafas.Products = Object.fromEntries(entries.filter(([id]) => supported.has(id)));
        this.adapter.log.debug(
            `[${this.serviceName}] Dropped products not supported by the active profile: ${dropped.join(', ')}`,
        );
        return { ...options, products };
    }

    /**
     * Suche nach Orten/Stationen.
     *
     * @param query Suchbegriff für Orte/Stationen
     * @param options optionale Suchoptionen
     */
    async getLocations(
        query: string,
        options?: Hafas.LocationsOptions,
    ): Promise<ReadonlyArray<Hafas.Station | Hafas.Stop | Hafas.Location>> {
        return this.call(client => client.locations(query, options));
    }

    /**
     * Liefert Abfahrten für eine gegebene Stations-ID.
     *
     * @param stationId ID der Station
     * @param options optionale Abfrage-Optionen
     */
    async getDepartures(stationId: string, options?: Hafas.DeparturesArrivalsOptions): Promise<Hafas.Departures> {
        const opts = this.sanitizeProducts(options);
        return this.call(client => client.departures(stationId, opts));
    }

    /**
     * Liefert Routeninformationen zwischen zwei Stationen.
     *
     * @param fromId ID der Startstation
     * @param toId ID der Zielstation
     * @param options optionale Routen-Optionen
     */
    async getJourneys(fromId: string, toId: string, options?: Hafas.JourneysOptions): Promise<Hafas.Journeys> {
        const opts = this.sanitizeProducts(options);
        return this.call(client => client.journeys(fromId, toId, opts));
    }

    /**
     * Holt Details zu einer Station/einem Haltpunkt.
     *
     * @param stationId ID der Station/des Haltpunkts
     * @param options optionale Abfrageoptionen
     */
    async getStop(
        stationId: string,
        options?: Hafas.StopOptions,
    ): Promise<Hafas.Station | Hafas.Stop | Hafas.Location> {
        return this.call(client => client.stop(stationId, options));
    }

    /**
     * Filtert Abfahrten auf die in der Konfiguration aktivierten Produkte.
     *
     * Gedacht für Backends ohne eigenen Client (EFA, TRIAS): Dort baut der Service die
     * Abfahrtsliste selbst und muss den Produktfilter nachbilden, den ein echter
     * hafas-client bereits serverseitig anwendet.
     *
     * Abfahrten **ohne** erkanntes Produkt bleiben bewusst erhalten – sie ganz auszublenden
     * hieße, eine Lücke in der Zuordnungstabelle als Anwenderwunsch auszugeben.
     *
     * @param departures Die bereits gemappten Abfahrten
     * @param products Der Produktfilter aus den Abfrage-Optionen
     */
    protected filterByProducts(departures: Hafas.Alternative[], products?: Hafas.Products): Hafas.Alternative[] {
        const active = Object.entries(products ?? {});
        if (active.length === 0) {
            return departures;
        }
        const allowed = new Set(active.filter(([, enabled]) => enabled).map(([id]) => id));
        if (allowed.size === 0) {
            return departures;
        }
        return departures.filter(departure => {
            const product = departure.line?.product;
            return !product || allowed.has(product);
        });
    }

    /**
     * Begrenzt Abfahrten auf das gewünschte Zeitfenster.
     *
     * @param departures Die bereits gemappten Abfahrten
     * @param when Beginn des Fensters (Standard: jetzt)
     * @param duration Länge des Fensters in Minuten
     */
    protected filterByDuration(
        departures: Hafas.Alternative[],
        when?: Date | string | number,
        duration?: number,
    ): Hafas.Alternative[] {
        if (!duration || duration <= 0) {
            return departures;
        }
        const start = when ? new Date(when).getTime() : Date.now();
        const end = start + duration * 60_000;
        return departures.filter(departure => {
            const time = Date.parse(departure.when ?? departure.plannedWhen ?? '');
            return !Number.isFinite(time) || time <= end;
        });
    }

    /**
     * Sortiert nach der **tatsächlichen** Zeit (Ist vor Soll).
     *
     * Grund ist ein realer Datenfall: Verbünde liefern die Liste nach der Sollzeit sortiert,
     * einzelne Nachtfahrten tragen aber Soll 00:00 mit einer Ist-Zeit Stunden später. Nach
     * Soll sortiert stünden sie oben in der Abfahrtstafel. Die Werte selbst bleiben unberührt.
     *
     * @param departures Die bereits gemappten Abfahrten
     */
    protected sortByEffectiveTime(departures: Hafas.Alternative[]): Hafas.Alternative[] {
        return [...departures].sort((a, b) => {
            const timeA = Date.parse(a.when ?? a.plannedWhen ?? '');
            const timeB = Date.parse(b.when ?? b.plannedWhen ?? '');
            if (!Number.isFinite(timeA) || !Number.isFinite(timeB)) {
                return 0;
            }
            return timeA - timeB;
        });
    }
}
